  "vertex PostOut post_vs(uint id [[vertex_id]]) {\n"
  "  PostOut o;\n"
  "  float2 p = float2((id << 1) & 2, id & 2);\n"
  "  o.clip = float4(p * 2 - 1, 0, 1);\n"
  "  o.uv = float2(p.x, 1 - p.y);\n"
  "  return o;\n"
  "}\n"
  "\n"
  "fragment float4 bright_fs(PostOut i [[stage_in]], texture2d<float> Tex0 [[texture(0)]], sampler Smp0 [[sampler(0)]]) {\n"
  "  float3 c = Tex0.sample(Smp0, i.uv).rgb;\n"
  "  float l = max(c.r, max(c.g, c.b));\n"
  "  return float4(c * saturate((l - 1.0) / max(l, 1e-4)), 1);\n"
  "}\n"
  "\n"
  "fragment float4 blur_fs(PostOut i [[stage_in]], constant PostData &U [[buffer(0)]], texture2d<float> Tex0 [[texture(0)]],\n"
  "                        sampler Smp0 [[sampler(0)]]) {\n"
  "  const float w[5] = { 0.227, 0.194, 0.121, 0.054, 0.016 };\n"
  "  float3 c = Tex0.sample(Smp0, i.uv).rgb * w[0];\n"
  "  for (int k = 1; k < 5; k++) {\n"
  "    c += Tex0.sample(Smp0, i.uv + U.P.zw * k).rgb * w[k];\n"
  "    c += Tex0.sample(Smp0, i.uv - U.P.zw * k).rgb * w[k];\n"
  "  }\n"
  "  return float4(c, 1);\n"
  "}\n"
  "\n"
  "static float3 aces(float3 x) { return saturate((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14)); }\n"
  "\n"
  "fragment float4 final_fs(PostOut i [[stage_in]], constant PostData &U [[buffer(0)]],\n"
  "                         texture2d<float> Tex0 [[texture(0)]], sampler Smp0 [[sampler(0)]],\n"
  "                         texture2d<float> Tex1 [[texture(1)]], sampler Smp1 [[sampler(1)]],\n"
  "                         texture2d<float> Tex2 [[texture(2)]], sampler Smp2 [[sampler(2)]],\n"
  "                         texture2d<float> Tex3 [[texture(3)]], sampler Smp3 [[sampler(3)]]) {\n"
  "  float2 uv = i.uv;\n"
  "  if (U.Hz.z > 0 && uv.y > U.Hz.x && uv.y < U.Hz.y) {\n"
  "    // heat shimmer, stronger toward the bottom of the band\n"
  "    float k = (uv.y - U.Hz.x) / max(U.Hz.y - U.Hz.x, 1e-3);\n"
  "    uv.x += sin(uv.y * 480 + U.Hz.w * 23) * sin(uv.y * 70 - U.Hz.w * 7) * U.Hz.z * k;\n"
  "  }\n"
  "  float3 hdr = float3(0);\n"
  "  int n = U.D.y != 0 ? 16 : 1;\n"
  "  for (int k = 0; k < n; k++) {\n"
  "    float2 q = uv + float2(U.D.y * 4.0 * k / 16.0, 0);\n"
  "    float3 s = Tex0.sample(Smp0, q).rgb + Tex1.sample(Smp1, q).rgb * U.P.y;\n"
  "    if (U.D.x < 1) s = mix(Tex3.sample(Smp3, q).rgb, s, U.D.x);\n"
  "    hdr += s / n;\n"
  "  }\n"
  "  float3 c = pow(aces(hdr * U.P.x), 1 / 2.2);\n"
  "  float2 d = i.uv - 0.5;\n"
  "  c *= 1 - dot(d, d) * (0.35 + U.G.y * 2.2);\n"
  "  c *= 1 + U.G.x * float3(0.5, 0.1, -0.4);\n"
  "  uint2 q = uint2(i.clip.xy);\n"
  "  uint h = q.x * 1973u + q.y * 9277u + uint(U.G.w * 60.0) * 26699u;\n"
  "  h = (h ^ (h >> 15)) * 0x2c1b3c6du;\n"
  "  h = (h ^ (h >> 12)) * 0x297a2d39u;\n"
  "  h ^= h >> 15;\n"
  "  float nz = float(h & 0xffffu) / 65535.0;\n"
  "  c += (nz - 0.5) * U.G.z * 0.45;\n"
  "  float4 ov = Tex2.sample(Smp2, i.uv);\n"
  "  return float4(ov.rgb + c * (1 - ov.a), 1);\n"
  "}\n";

#endif
